// The exercise library installed with the app (spec section 5, Seed; GYM-149): 831 exercises
// from the owner's merged library. exercises.json is generated by scripts/build-seed.mjs and
// committed; never edit it by hand. Sources and licences: THIRD_PARTY_NOTICES.md.
import type {
  Equipment,
  Level,
  Mechanic,
  Muscle,
  Pattern,
  Subcategory,
  TrainingType,
} from '../../domain/catalogue';
import seed from './exercises.json';

export type SeedExercise = {
  nameEn: string;
  namePl: string;
  /** Other names, searched like the English and Polish ones (the old app names among them). */
  aliases: string[];
  /** null for cardio. */
  pattern: Pattern | null;
  subcategory: Subcategory | null;
  trainingType: TrainingType;
  equipment: Equipment;
  primaryMuscles: Muscle[];
  secondaryMuscles: Muscle[];
  mechanic: Mechanic | null;
  level: Level | null;
  unilateral: boolean;
  usesBodyweight: boolean;
  /** 1 = most common, listed first; 4 = really uncommon. */
  importance: 1 | 2 | 3 | 4;
};

/** The library version this seed brings. Phones below it get the one-time upgrade (syncLibrary). */
export const SEED_VERSION = 2;

// The generator validates every value against the fixed lists, and data/__tests__/seed.test.ts
// checks the committed file again, so the cast only restores the literal types JSON loses.
export const SEED_EXERCISES = seed as SeedExercise[];
